package org.example.spotifymixer.runtime;
import android.content.*;import android.os.*;import android.security.keystore.*;import android.util.Base64;import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.*;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;import org.json.*;import java.util.*;import java.util.concurrent.*;
/** HTTPS server-authoritative membership. No persisted premium flag, password or Spotify credentials. */
public final class Auth {
 private static final String BASE="https://spotenhancer.sourcemod.lol/api/index.php?route=",ALIAS="spotenhancer-account-v1";
 private static final Handler MAIN=new Handler(Looper.getMainLooper());private static final ExecutorService IO=Executors.newSingleThreadExecutor();
 private static Context app;private static SharedPreferences storage;private static String token;private static volatile String username="",notice="Free · Sign in to connect your account";private static volatile boolean premium,busy;private static volatile long verifiedUntil;private static volatile long premiumExpiry;
 private static final Set<Runnable> listeners=new HashSet<>();private static final Runnable EXPIRY=()->{premium=false;verifiedUntil=0;changed();refresh();};
 public static void attach(Context context){if(app!=null)return;app=context.getApplicationContext();storage=app.getSharedPreferences("spotenhancer-account-secure-v1",0);try{String saved=storage.getString("session",null);if(saved!=null)token=decrypt(saved);}catch(Exception e){storage.edit().clear().commit();notice="Saved session unavailable. Sign in again.";}if(token!=null)refresh();}
 public static boolean allowed(String id){return AccessPolicy.allowed(id,premium&&SystemClock.elapsedRealtime()<verifiedUntil);}
 public static boolean enabled(SharedPreferences prefs,String id){String key=id.equals("equalizer")?"eq_enabled":id.equals("themes")?"theme_enabled":id+"_enabled";return allowed(id)&&prefs.getBoolean(key,false);}
 public static void require(String id){if(!allowed(id))throw new IllegalStateException("SpotEnhancer Premium is required for this feature.");}
 public static String username(){return username;}public static String status(){return notice;}public static boolean busy(){return busy;}public static boolean signedIn(){return token!=null;}public static long premiumExpiry(){return premiumExpiry;}
 public static void listen(Runnable listener){listeners.add(listener);}public static void unlisten(Runnable listener){listeners.remove(listener);}
 private static void safely(Runnable action){try{action.run();}catch(RuntimeException|LinkageError error){Diagnostics.event("Account UI refresh unavailable: "+error.getClass().getSimpleName());}}
 private static void changed(){if(app!=null){safely(()->ThemeRuntime.refresh(app));safely(EqualizerRuntime::refresh);safely(EnhancementRuntime::refresh);}for(Runnable r:new ArrayList<>(listeners))safely(r);}
 public static void refresh(){if(app==null||token==null||busy)return;request("session",new JSONObject(),false);}
 public static void credentials(String route,String name,String password){if(!route.equals("login")&&!route.equals("register"))throw new IllegalArgumentException("Invalid account action");if(name==null||!name.matches("[A-Za-z0-9_]{3,32}"))throw new IllegalArgumentException("Use 3–32 letters, digits or underscores");int bytes=password==null?0:password.getBytes(StandardCharsets.UTF_8).length;if(bytes<12||bytes>128)throw new IllegalArgumentException("Use a password of 12–128 bytes");try{request(route,new JSONObject().put("username",name).put("password",password),true);}catch(JSONException e){throw new IllegalStateException(e);}}
 private static void request(String route,JSONObject body,boolean login){if(app==null||busy)return;busy=true;notice=login?"Connecting account…":"Checking membership…";String expected=token;changed();IO.execute(()->{JSONObject response=null;Exception failure=null;try{response=call(route,body,expected);}catch(Exception e){failure=e;}JSONObject result=response;Exception error=failure;MAIN.post(()->{busy=false;if(!Objects.equals(expected,token)){changed();return;}try{if(error!=null)throw error;if(login){String next=result.getString("token");if(!next.matches("[a-f0-9]{64}"))throw new IOException("Invalid session response");String encrypted=encrypt(next);if(!storage.edit().putString("session",encrypted).commit())throw new IOException("Could not save session");token=next;}JSONObject account=result.getJSONObject("account");username=account.getString("username");long now=account.getLong("checked_at"),until=account.getLong("premium_until"),session=account.getLong("session_expires_at");premiumExpiry=until;long ttl=Math.max(0,Math.min(300,Math.min(until-now,session-now)));premium="premium".equals(account.getString("plan"))&&ttl>0;verifiedUntil=SystemClock.elapsedRealtime()+ttl*1000;notice=premium?"Premium · "+username:"Free · "+username;MAIN.removeCallbacks(EXPIRY);MAIN.postDelayed(EXPIRY,premium?ttl*1000:240000);}catch(Exception e){premium=false;verifiedUntil=0;notice=e.getMessage()==null?"Account connection failed":e.getMessage();if(e instanceof Unauthorized){clear();notice="Session expired. Sign in again.";}else if(token!=null){MAIN.removeCallbacks(EXPIRY);MAIN.postDelayed(EXPIRY,240000);}}changed();});});}
 public static void logout(boolean all){if(app==null||busy)return;String old=token;clear();notice="Signed out · Free";changed();if(old!=null)IO.execute(()->{try{call(all?"logout-all":"logout",new JSONObject(),old);}catch(Exception ignored){}});}
 private static void clear(){token=null;username="";premium=false;premiumExpiry=0;verifiedUntil=0;MAIN.removeCallbacks(EXPIRY);if(storage!=null)storage.edit().clear().commit();}
 private static final class Unauthorized extends IOException{}
 private static JSONObject call(String route,JSONObject body,String session)throws Exception{
  HttpURLConnection c=(HttpURLConnection)new URL(BASE+route).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(15000);c.setRequestMethod("POST");c.setRequestProperty("Content-Type","application/json");if(session!=null)c.setRequestProperty("Authorization","Bearer "+session);c.setDoOutput(true);
  try{byte[] bytes=body.toString().getBytes(StandardCharsets.UTF_8);c.setFixedLengthStreamingMode(bytes.length);try(OutputStream out=c.getOutputStream()){out.write(bytes);}int status=c.getResponseCode();if(status==401&&!route.equals("login"))throw new Unauthorized();InputStream source=status>=200&&status<300?c.getInputStream():c.getErrorStream();if(source==null)throw new IOException("Account service unavailable ("+status+")");ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=source){byte[] buffer=new byte[1024];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>8192)throw new IOException("Invalid account response");out.write(buffer,0,n);}}JSONObject result=new JSONObject(out.toString("UTF-8"));if(status<200||status>=300)throw new IOException(result.optString("error","Account service unavailable"));return result;}finally{c.disconnect();}
 }
 private static SecretKey key()throws Exception{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);if(ks.containsAlias(ALIAS))return (SecretKey)ks.getKey(ALIAS,null);KeyGenerator g=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder(ALIAS,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());return g.generateKey();}
 private static String encrypt(String value)throws Exception{Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key());return Base64.encodeToString(cipher.getIV(),Base64.NO_WRAP)+":"+Base64.encodeToString(cipher.doFinal(value.getBytes(StandardCharsets.UTF_8)),Base64.NO_WRAP);}
 private static String decrypt(String value)throws Exception{String[] parts=value.split(":",-1);if(parts.length!=2)throw new IOException("Invalid saved session");Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Base64.decode(parts[0],Base64.NO_WRAP)));String result=new String(cipher.doFinal(Base64.decode(parts[1],Base64.NO_WRAP)),StandardCharsets.UTF_8);if(!result.matches("[a-f0-9]{64}"))throw new IOException("Invalid saved token");return result;}
 private Auth(){}
}
